106	/**
107	 * A seeded match seen from outside: ships sail and turn, players collect sealed sources and claim caches, fight duels
108	 * (reserving their rubbings) that end in a theft or a draw, leave (their rubbings go into a cache where they were)
109	 * and join, and buy targeted rumors, sometimes repeating a request id. Some scenarios jump several ticks at once.
110	 */
111	function randomScript(scenario: Scenario, config: IntelConfig, map: IntelMapShape): IntelReplayTick[] {
112	  const draw = generator(scenario.seed);
113	  const chance = (perMille: number) => draw(1000) < perMille;
114	  const preset = rulesPresets[scenario.preset];
115	  const width = map.widthTiles * T;
116	  const height = map.heightTiles * T;
117	  const players = new Map<string, SimPlayer>();
118	  let nextPlayer = 0;
119	  const join = () => {
120	    players.set(`crew-${nextPlayer++}`, { x: draw(width), y: draw(height), heading: draw(8) });
121	  };
122	  for (let index = 0; index < preset.maxPlayers; index++) join();
123	  const rubbings = new Map<string, IntelRubbing>();
124	  const deck = presetRubbings(preset);
125	  deck.forEach((rubbing, index) => {
126	    const island = Math.floor(index / preset.sourcesPerIsland);
127	    // Spread each type over the islands: deal by a seeded shuffle of the deck positions.
128	    rubbings.set(rubbing.id, { id: rubbing.id, type: rubbing.type, place: { kind: "source", island, ...islandPoint(map, island) } });
129	  });
130	  // Shuffle which type sits on which island.
131	  const ids = [...rubbings.keys()];
132	  for (let index = ids.length - 1; index > 0; index--) {
133	    const other = draw(index + 1);
134	    const a = rubbings.get(ids[index]!)!;
135	    const b = rubbings.get(ids[other]!)!;
136	    rubbings.set(a.id, { ...a, place: b.place });
137	    rubbings.set(b.id, { ...b, place: a.place });
138	  }
139	  const duels: { a: string; b: string; until: number }[] = [];
140	  const inDuel = (id: string) => duels.some((duel) => duel.a === id || duel.b === id);
141	  const heldTypes = (id: string) =>
142	    [...rubbings.values()].filter((rubbing) => (rubbing.place.kind === "carried" || rubbing.place.kind === "duel") && rubbing.place.playerId === id).map((rubbing) => rubbing.type);
143	  const pick = <T>(items: readonly T[]): T | undefined => (items.length === 0 ? undefined : items[draw(items.length)]);
144	  const requestIds: string[] = [];
145	
146	  const script: IntelReplayTick[] = [];
