155	      player.y = Math.min(Math.max(player.y + dy * 64 * dt, 0), height - 1);
156	      if (player.x === 0 || player.y === 0 || player.x === width - 1 || player.y === height - 1) player.heading = draw(8);
157	    }
158	    const free = [...players.keys()].filter((id) => !inDuel(id));
