247	/** What a view says, for checking messages against it. */
248	interface Facts {
249	  readonly players: ReadonlySet<string>;
250	  readonly held: ReadonlyMap<string, readonly RubbingType[]>;
251	  readonly sourceIslands: readonly { type: RubbingType; island: number }[];
252	  readonly cacheSectors: readonly { type: RubbingType; sector: number }[];
253	  readonly carriers: readonly { type: RubbingType; sector: number; holder: string }[];
254	}
255	
256	function factsOf(config: IntelConfig, view: IntelWorldView): Facts {
257	  const positions = new Map(view.players.map((player) => [player.id, player]));
258	  const held = new Map<string, RubbingType[]>(view.players.map((player) => [player.id, []]));
259	  const sourceIslands: { type: RubbingType; island: number }[] = [];
260	  const cacheSectors: { type: RubbingType; sector: number }[] = [];
261	  const carriers: { type: RubbingType; sector: number; holder: string }[] = [];
262	  for (const rubbing of view.rubbings) {
263	    const place = rubbing.place;
264	    if (place.kind === "source") sourceIslands.push({ type: rubbing.type, island: place.island });
265	    else if (place.kind === "cache") cacheSectors.push({ type: rubbing.type, sector: sectorOf(config, place) });
266	    else {
267	      held.get(place.playerId)!.push(rubbing.type);
268	      carriers.push({ type: rubbing.type, sector: sectorOf(config, positions.get(place.playerId)!), holder: place.playerId });
269	    }
270	  }
271	  return { players: new Set(positions.keys()), held, sourceIslands, cacheSectors, carriers };
272	}
