307	
308	function allStrings(value: unknown, out: string[] = []): string[] {
309	  if (typeof value === "string") out.push(value);
310	  else if (Array.isArray(value)) for (const item of value) allStrings(item, out);
311	  else if (typeof value === "object" && value !== null) for (const item of Object.values(value)) allStrings(item, out);
312	  return out;
313	}
314	
315	/**
316	 * Checks every message of a run against the design's rules (§3, §5, §11, §16), with the views that produced them. It
317	 * returns nothing and throws on the first violation, with the tick and message.
318	 */
319	class Checker {
320	  private readonly rumors = new Map<string, { type: RubbingType; closed: boolean; target: unknown }>();
321	  private readonly sightings = new Map<string, number>();
322	  private readonly carriersAt = new Map<number, Facts["carriers"]>();
323	  private readonly ids = new Set<string>();
324	  private previousTick = -Infinity;
325	  private previousState: IntelState | undefined;
326	
327	  constructor(
328	    private readonly config: IntelConfig,
329	    private readonly skipping: boolean,
330	  ) {}
331	
332	  check(view: IntelWorldView, messages: readonly IntelMessage[], state: IntelState): void {
333	    const config = this.config;
334	    const tick = view.tick;
335	    if (tick - this.previousTick > 1 && this.previousTick >= config.controlStartTick) EXERCISED.add("skipped-ticks");
336	    this.previousTick = tick;
337	    const facts = factsOf(config, view);
338	    this.carriersAt.set(tick, facts.carriers);
339	    for (const player of view.players) this.ids.add(player.id);
340	    for (const rubbing of view.rubbings) this.ids.add(rubbing.id);
341	    if (state.players.some((player) => player.pending !== null)) EXERCISED.add("sighting:deferred");
342	    const fail = (message: IntelMessage, why: string): never => {
343	      throw new Error(`tick ${tick}: ${why}: ${JSON.stringify(message)}`);
344	    };
345	    if (tick < config.controlStartTick && messages.length > 0) fail(messages[0]!, "a message before control start");
346	    // Who had already spent this snapshot's sighting before this step.
347	    const snapshotIndex = Math.floor((tick - config.controlStartTick) / config.carrierIntervalTicks);
348	    const cappedBefore = new Set(
349	      tick >= config.controlStartTick && tick < config.carrierRevealTick ? [...facts.players].filter((id) => this.sightings.has(`${id}@${snapshotIndex}`)) : [],
350	    );
351	    const sightedThisStep = new Set<string>();
352	    for (const message of messages) {
353	      const body = message.body;
354	      EXERCISED.add(`message:${body.kind}`);
355	      if (body.tick !== tick) fail(message, "wrong tick");
356	      // Keys: exactly the allowed ones, nested ones from the small sector/target vocabulary.
357	      expect(Object.keys(body).sort()).toEqual([...BODY_KEYS[body.kind]]);
358	      for (const nested of ["target", "sources", "caches", "carriers", "sightings"] as const) {
359	        const value = (body as Record<string, unknown>)[nested];
360	        if (value === undefined) continue;
361	        for (const item of Array.isArray(value) ? value : [value]) {
362	          for (const key of Object.keys(item as object)) if (!NESTED_KEYS.has(key)) fail(message, `nested key ${key}`);
363	        }
364	      }
365	      // No id anywhere in a body.
366	      for (const text of allStrings(body)) if (this.ids.has(text)) fail(message, `the id ${text} leaks`);
367	      // Addressing: broadcasts to everyone, everything else to one player present now.
368	      if (BROADCASTS.has(body.kind)) {
369	        if (message.to.kind !== "everyone") fail(message, "a broadcast addressed to someone");
370	        continue;
371	      }
372	      if (message.to.kind !== "player" || !facts.players.has(message.to.playerId)) fail(message, "not addressed to one present player");
373	      const recipient = (message.to as { playerId: string }).playerId;
374	      const held = facts.held.get(recipient)!;
375	      const complete = config.types.every((type) => held.includes(type));
376	      const key = (entry: number) => `${recipient}#${entry}`;
377	      switch (body.kind) {
378	        case "final-route":
379	          // The only exact position ever sent, and only to a full-set holder.
380	          if (!complete || body.x !== config.finalIsland.x || body.y !== config.finalIsland.y) fail(message, "a route to a player without a full set");
381	          if (body.restored) EXERCISED.add("route:restored");
382	          break;
383	        case "final-route-inactive":
384	          if (complete) fail(message, "a route suspended for a full set");
385	          break;
386	        case "rumor": {
387	          EXERCISED.add(`rumor:${body.reason}`);
388	          EXERCISED.add(`rumor:${body.target.kind}`);
389	          if (held.includes(body.type)) fail(message, "a rumor for a held type");
390	          const target = body.target;
391	          const there =
392	            target.kind === "island"
393	              ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
394	              : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
395	          if (!there) fail(message, "a rumor pointing at nothing");
396	          // Sources before caches: a cache lead only when no sealed source of the type is left outside the journal.
397	          if (target.kind === "sector") {
398	            const journaled = this.activeIslands(recipient, body.type);
399	            if (facts.sourceIslands.some((source) => source.type === body.type && !journaled.has(source.island))) {
400	              fail(message, "a cache rumor while an eligible sealed source existed");
401	            }
402	          }
403	          if (this.rumors.has(key(body.entry))) fail(message, "a journal entry reused");
404	          this.rumors.set(key(body.entry), { type: body.type, closed: false, target });
405	          break;
406	        }
407	        case "rumor-stale":
408	        case "rumor-resolved": {
409	          // Only journal rumors close; a carrier sighting has no entry, so it can never go stale.
410	          const rumor = this.rumors.get(key(body.entry));
411	          if (rumor === undefined || rumor.closed || rumor.type !== body.type) fail(message, "closing no open journal rumor");
412	          rumor!.closed = true;
413	          if (body.kind === "rumor-resolved" && !held.includes(body.type)) fail(message, "resolved without the type");
414	          if (body.kind === "rumor-stale") {
415	            if (held.includes(body.type)) fail(message, "stale although the holder has the type");
416	            const target = rumor!.target as { kind: "island"; island: number } | { kind: "sector"; sector: number };
417	            const there =
418	              target.kind === "island"
419	                ? facts.sourceIslands.some((source) => source.type === body.type && source.island === target.island)
420	                : facts.cacheSectors.some((cache) => cache.type === body.type && cache.sector === target.sector);
421	            if (there) fail(message, "stale while the target still holds the type");
422	          }
423	          break;
424	        }
425	        case "carrier-sighting": {
426	          if (body.sightings.length === 0) fail(message, "a sighting message with no sighting");
427	          if (sightedThisStep.has(recipient)) fail(message, "a second sighting message in one step");
428	          sightedThisStep.add(recipient);
429	          if (new Set(body.sightings.map((sighting) => sighting.type)).size !== body.sightings.length) fail(message, "a type sighted twice in one message");
430	          if (body.sightings.length > 1) EXERCISED.add("sighting:several-types");
431	          if (body.seenTick >= tick) fail(message, "a sighting of the present");
432	          const age = tick - body.seenTick;
433	          const interval = config.carrierIntervalTicks;
434	          if (!this.skipping && (age < interval || age >= 2 * interval)) fail(message, `a sighting ${age} ticks old`);
435	          const then = this.carriersAt.get(body.seenTick);
436	          if (then === undefined) fail(message, "a sighting of a tick never seen");
437	          for (const sighting of body.sightings) {
438	            EXERCISED.add(`sighting:${sighting.reason}`);
439	            if (held.includes(sighting.type)) fail(message, "a sighting for a held type");
440	            if (!then!.some((carrier) => carrier.type === sighting.type && carrier.sector === sighting.sector && carrier.holder !== recipient)) {
441	              fail(message, "a sighting of no other carrier");
442	            }
443	            // Carriers last: a sighting only when no source or cache of the type exists at all.
444	            if (facts.sourceIslands.some((source) => source.type === sighting.type) || facts.cacheSectors.some((cache) => cache.type === sighting.type)) {
445	              fail(message, "a carrier sighting while a source or cache existed");
446	            }
447	          }
448	          if (tick < config.carrierRevealTick) {
449	            const snapshot = `${recipient}@${Math.floor((tick - config.controlStartTick) / interval)}`;
450	            const count = (this.sightings.get(snapshot) ?? 0) + 1;
451	            if (count > 1) fail(message, "a second sighting message in one snapshot");
452	            this.sightings.set(snapshot, count);
453	          }
454	          break;
455	        }
456	        case "no-lead":
457	          if (held.includes(body.type)) fail(message, "a no-lead for a held type");
458	          break;
459	      }
460	    }
461	    this.checkPending(tick, facts, messages, state);
462	    this.checkFreeTriggers(tick, facts, messages, state, cappedBefore);
463	    this.previousState = state;
464	  }
465	
466	  /**
467	   * Every free trigger of this step (a type lost, or a journal rumor gone stale) whose type needs a carrier sighting
468	   * is in this step's sighting message or in the pending set, never in neither; and it waits only when the player's
469	   * sighting was already spent in this snapshot or the previous snapshot shows no other carrier of it. The pending set
470	   * then goes out at the next boundary (`checkPending`).
471	   */
472	  private checkFreeTriggers(tick: number, facts: Facts, messages: readonly IntelMessage[], state: IntelState, cappedBefore: ReadonlySet<string>): void {
473	    const previous = this.previousState;
474	    if (previous === undefined || !previous.started) return;
475	    const older = state.snapshots.length === 2 ? state.snapshots[0]! : undefined;
476	    const olderCarriers = older === undefined ? [] : this.carriersAt.get(older.tick)!;
477	    for (const now of state.players) {
478	      const before = previous.players.find((player) => player.id === now.id);
479	      if (before === undefined) continue;
480	      const held = facts.held.get(now.id)!;
481	      const mine = messages.filter((message) => message.to.kind === "player" && message.to.playerId === now.id).map((message) => message.body);
482	      const triggered = new Set([
483	        ...before.held.filter((type) => !held.includes(type)),
484	        ...mine.flatMap((body) => (body.kind === "rumor-stale" ? [body.type] : [])),
485	      ]);
486	      const sighted = new Set(mine.flatMap((body) => (body.kind === "carrier-sighting" ? body.sightings.map((sighting) => sighting.type) : [])));
487	      for (const type of triggered) {
488	        const needsSighting =
489	          !held.includes(type) &&
490	          !facts.sourceIslands.some((source) => source.type === type) &&
491	          !facts.cacheSectors.some((cache) => cache.type === type) &&
492	          facts.carriers.some((carrier) => carrier.type === type && carrier.holder !== now.id);
493	        if (!needsSighting || sighted.has(type)) continue;
494	        if (!(now.pending?.types.some((pending) => pending.type === type) ?? false)) throw new Error(`tick ${tick}: ${now.id}'s free ${type} trigger was neither sighted nor queued`);
495	        const readable = olderCarriers.some((carrier) => carrier.type === type && carrier.holder !== now.id);
496	        if (readable && !cappedBefore.has(now.id)) throw new Error(`tick ${tick}: ${now.id}'s free ${type} trigger waits although the sighting was not spent`);
497	        EXERCISED.add("sighting:free-deferred");
498	      }
499	      if (sighted.size > 0 && [...triggered].some((type) => sighted.has(type))) EXERCISED.add("sighting:free-same-step");
500	    }
501	  }
502	
503	  /** The islands of the player's journal rumors for the type that are still open. */
504	  private activeIslands(playerId: string, type: RubbingType): Set<number> {
505	    const islands = new Set<number>();
506	    for (const [key, rumor] of this.rumors) {
507	      if (!key.startsWith(`${playerId}#`) || rumor.closed || rumor.type !== type) continue;
508	      const target = rumor.target as { kind: string; island?: number };
509	      if (target.kind === "island") islands.add(target.island!);
510	    }
511	    return islands;
512	  }
513	
514	  /**
515	   * After every step, each player has at most one pending sighting message holding a set of types. At the first
516	   * boundary after a type was deferred, it goes out in a sighting, unless the checker finds it ineligible (held, a
517	   * source or cache exists, or no one else carries it), or finds no other carrier of it in the previous snapshot to
518	   * read, in which case it must still be pending.
519	   */
520	  private checkPending(tick: number, facts: Facts, messages: readonly IntelMessage[], state: IntelState): void {
521	    const fail = (why: string): never => {
522	      throw new Error(`tick ${tick}: ${why}`);
523	    };
524	    for (const player of state.players) {
525	      if (player.pending === null) continue;
526	      const types = player.pending.types.map((pending) => pending.type);
527	      if (types.length === 0) fail(`${player.id} has an empty pending message`);
528	      if (new Set(types).size !== types.length) fail(`${player.id} has a type pending twice`);
529	    }
530	    const previous = this.previousState;
531	    const newest = state.snapshots.at(-1);
532	    if (previous === undefined || newest === undefined || newest.boundary <= (previous.snapshots.at(-1)?.boundary ?? -1)) return;
533	    const older = state.snapshots.length === 2 ? state.snapshots[0]! : undefined;
534	    const olderCarriers = older === undefined ? [] : this.carriersAt.get(older.tick)!;
535	    for (const before of previous.players) {
536	      const now = state.players.find((player) => player.id === before.id);
537	      if (before.pending === null || now === undefined) continue;
538	      const sighted = new Set(
539	        messages.flatMap((message) =>
540	          message.to.kind === "player" && message.to.playerId === before.id && message.body.kind === "carrier-sighting"
541	            ? message.body.sightings.map((sighting) => sighting.type)
542	            : [],
543	        ),
544	      );
545	      for (const { type } of before.pending.types) {
546	        const stillPending = now.pending?.types.some((pending) => pending.type === type) ?? false;
547	        const eligible =
548	          !facts.held.get(before.id)!.includes(type) &&
549	          !facts.sourceIslands.some((source) => source.type === type) &&
550	          !facts.cacheSectors.some((cache) => cache.type === type) &&
551	          facts.carriers.some((carrier) => carrier.type === type && carrier.holder !== before.id);
552	        const readable = olderCarriers.some((carrier) => carrier.type === type && carrier.holder !== before.id);
553	        if (sighted.has(type)) EXERCISED.add("sighting:deferred-delivered");
554	        else if (eligible && readable) fail(`${before.id}'s deferred ${type} sighting was not delivered at the boundary`);
555	        else if (eligible && !stillPending) fail(`${before.id}'s deferred ${type} sighting was dropped while eligible`);
556	        else if (!eligible && stillPending) fail(`${before.id}'s deferred ${type} sighting is still pending although ineligible`);
557	      }
558	    }
559	  }
560	}
561	
562	function setup(scenario: Scenario) {
563	  const map = scenario.preset === "slice" ? SLICE_MAP : ALPHA_MAP;
564	  const config = createIntelConfig({
565	    preset: scenario.preset,
566	    finalIsland: { x: (map.widthTiles * T) >> 1, y: ((map.heightTiles * T) >> 1) + 77 },
567	    controlStartTick: START,
568	    map,
569	    ...(scenario.realTimes ? {} : { rules: QUICK_RULES }),
570	  });
571	  return { config, script: randomScript(scenario, config, map) };
572	}
573	
574	describe("intel property runs (§3, §5, §11, §16)", () => {
575	  for (const scenario of SCENARIOS) {
576	    it(`keep every message within the rules: ${scenario.name}`, { timeout: 120_000 }, () => {
577	      const { config, script } = setup(scenario);
578	      if (scenario.realTimes && scenario.skipPerMille === 0) {
579	        expect(config.carrierIntervalTicks).toBe(600);
580	        expect(script.at(-1)!.view.tick - config.controlStartTick).toBeGreaterThanOrEqual(36_000);
581	        expect(script.at(-1)!.view.tick).toBeGreaterThan(config.carrierRevealTick + 4 * config.carrierIntervalTicks);
582	      }
583	      const checker = new Checker(config, scenario.skipPerMille > 0);
584	      let state = createIntelState(config, scenario.seed);
585	      const kinds = new Set<string>();
586	      const messages: IntelMessage[] = [];
587	      for (const { view, requests } of script) {
588	        // Frozen (views are frozen too), so a step that wrote into its input would throw.
589	        const stepped = stepIntel(config, deepFreeze(state), view, requests ?? []);
590	        messages.push(...stepped.messages);
591	        expect(stepped.outcomes.map((outcome) => outcome.requestId)).toEqual((requests ?? []).map((request) => request.requestId));
592	        for (const outcome of stepped.outcomes) EXERCISED.add(`outcome:${outcome.result}`);
593	        checker.check(view, stepped.messages, stepped.state);
594	        for (const message of stepped.messages) kinds.add(message.body.kind);
595	        state = stepped.state;
596	      }
597	      // The run reached the reveals it spans.
598	      expect(kinds.has("sector-reveal") && kinds.has("carrier-report")).toBe(true);
599	      // Replaying the same script from the same seed reaches the same state.
600	      const replayed = replayIntel(config, createIntelState(config, scenario.seed), script);
601	      expect(replayed.hash).toBe(hashState(state));
602	      expect(replayed.messages).toEqual(messages);
603	    });
604	  }
605	
606	  it("exercise every message kind, outcome and lead path (EXERCISED)", () => {
607	    expect(MUST_EXERCISE.filter((path) => !EXERCISED.has(path))).toEqual([]);
608	  });
609	});
